y = spo2_at_rr[valid] if len(valid) > 0 else np.array([])
tmin = rr_min[valid] if len(valid) > 0 else np.array([])
w_lo, w_hi = (250.0, 270.0)
in_win = (tmin >= w_lo) & (tmin <= w_hi) if len(tmin) > 0 else np.array([], dtype=bool)
fig, ax = plt.subplots(figsize=(9.5, 6.5))
if len(tmin) > 0 and np.any(~in_win):
    sc = ax.scatter(x[~in_win], y[~in_win], c=tmin[~in_win], cmap='viridis', s=38, alpha=0.85, edgecolors='none')
else:
    sc = None
if len(tmin) > 0 and np.any(in_win):
    ax.scatter(x[in_win], y[in_win], c=tmin[in_win], cmap='viridis', s=80, alpha=1.0, edgecolors='black', linewidths=0.9, marker='o', zorder=3)
ax.set_xlabel('RR × Shock Index (breaths/min × unitless)')
ax.set_ylabel('SpO₂ (%)')
ax.set_title('Phase-space: (RR×Shock Index) vs SpO₂, colored by time; 250–270 min highlighted')
if sc is not None:
    cbar = plt.colorbar(sc, ax=ax)
    cbar.set_label('Minutes since start')
ax.text(0.01, 0.02, f'Highlighted window: {w_lo:.0f}–{w_hi:.0f} min', transform=ax.transAxes, ha='left', va='bottom', fontsize=10)
ax.grid(True, alpha=0.25)
save_plot('phase_space_rrXsi_vs_spo2_timecolored_highlight_250_270min.png', fig=fig)
n_total = int(len(tmin))
n_win = int(np.sum(in_win)) if len(tmin) > 0 else 0
spo2_win_min = float(np.nanmin(y[in_win])) if n_win > 0 else np.nan
spo2_win_mean = float(np.nanmean(y[in_win])) if n_win > 0 else np.nan
rrxsi_win_mean = float(np.nanmean(x[in_win])) if n_win > 0 else np.nan
result = {'shock_index_used': float(shock_index), 'n_points_total': n_total, 'n_points_in_250_270min_window': n_win, 'window_minutes': (w_lo, w_hi), 'spo2_in_window_min_pct': spo2_win_min, 'spo2_in_window_mean_pct': spo2_win_mean, 'rr_x_shock_index_in_window_mean': rrxsi_win_mean, 'plot_file': 'phase_space_rrXsi_vs_spo2_timecolored_highlight_250_270min.png'}
interpretation = f'Phase-space plot of (RR×Shock Index) vs SpO₂ colored by time with the 250–270 min window highlighted: {n_win}/{n_total} paired RR–SpO₂ points fall in the window; within-window SpO₂ min/mean={spo2_win_min:.1f}/{spo2_win_mean:.1f}% and mean RR×SI={rrxsi_win_mean:.2f}, supporting visual assessment for clustering/discordance (tachypnea–shock physiology vs hypoxemia-linked events).'

plt.close()